const q = $json.query || {};
const mode = q['hub.mode'];
const token = q['hub.verify_token'];
const challenge = q['hub.challenge'];
const expected = $env.META_VERIFY_TOKEN || '0931234d935978f4527ec724e1a9c60e';

if (mode === 'subscribe' && token === expected) {
  return [{ json: { ok: true, challenge } }];
}

return [{ json: { ok: false, error: 'Verification token mismatch' } }];

const value = $json.body?.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0] || null;
const statuses = value.statuses || [];

if (!msg) {
  return [{ json: {
    route: statuses.length ? 'status' : 'ignore',
    raw: $json.body,
    value,
    statuses,
  }}];
}

const isFlowReply = msg.type === 'interactive' && msg.interactive?.type === 'nfm_reply';
const isButtonReply =
  (msg.type === 'button' && !!msg.button?.payload) ||
  (msg.type === 'interactive' && msg.interactive?.type === 'button_reply' && !!msg.interactive?.button_reply?.id) ||
  (msg.type === 'interactive' && msg.interactive?.type === 'list_reply' && !!msg.interactive?.list_reply?.id);

const phoneNumberId = value.metadata?.phone_number_id || '';
const waId = value.contacts?.[0]?.wa_id || msg.from || '';
const profileName = value.contacts?.[0]?.profile?.name || '';
const buttonPayload = msg.button?.payload || msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '';
const buttonText = msg.button?.text || msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

let route = 'normal';
if (isFlowReply) route = 'flow';
else if (isButtonReply) route = 'button_reply';

$execution.customData.set('tipo', route);

return [{ json: {
  route,
  phone_number_id: phoneNumberId,
  wa_id: waId,
  profile_name: profileName,
  message_id: msg.id || '',
  timestamp: msg.timestamp || '',
  flow_token: msg.interactive?.nfm_reply?.flow_token || '',
  flow_name: msg.interactive?.nfm_reply?.name || '',
  response_json: msg.interactive?.nfm_reply?.response_json || {},
  button_payload: buttonPayload,
  button_text: buttonText,
  msg,
  raw: $json.body,
}}];

const item = JSON.parse(JSON.stringify($json));

function parseResponseJson(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return { raw_response_json: String(value) };
  }
}

function formatValue(value) {
  if (Array.isArray(value)) {
    return value.join(', ');
  }
  if (value && typeof value === 'object') {
    return JSON.stringify(value);
  }
  if (value === null || value === undefined || value === '') {
    return '-';
  }
  return String(value);
}

const data = parseResponseJson(item.response_json);

const lines = [];
for (const [key, value] of Object.entries(data)) {
  lines.push(`${key}: ${formatValue(value)}`);
}

const textBody = lines.join('\n');

const msg = item.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];

if (!msg) {
  throw new Error('No se encontró raw.entry[0].changes[0].value.messages[0]');
}

// mantener todo igual y cambiar SOLO messages[0]
msg.type = 'text';
msg.text = {
  body: textBody
};

// quitar la parte interactiva
// delete msg.interactive;
// opcional: quitar context para que se parezca más al mensaje normal
// delete msg.context;

return [
  {
    json: item
  }
];

const item = JSON.parse(JSON.stringify($json));

const msg = item.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg) {
  throw new Error('No se encontró raw.entry[0].changes[0].value.messages[0]');
}

const payload = String(item.button_payload || msg.button?.payload || msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '').trim();
const buttonText = String(item.button_text || msg.button?.text || msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '').trim();
const listDescription = String(msg.interactive?.list_reply?.description || '').trim();
const isListReply = msg.type === 'interactive' && msg.interactive?.type === 'list_reply';

let model = '';
let action = '';

if (payload.includes('__')) {
  const parts = payload.split('__');
  model = String(parts[0] || '').trim();
  action = String(parts.slice(1).join('__') || '').trim();
}

const textLines = isListReply
  ? [
      'list_reply_id: ' + (payload || '-'),
      'list_reply_title: ' + (buttonText || '-'),
      'list_reply_description: ' + (listDescription || '-'),
      'selected_establishment_name: ' + (buttonText || '-'),
      'selected_establishment_id: ' + (payload.startsWith('est__') ? payload.slice(5) : '-'),
      'button_payload: ' + (payload || '-'),
    ]
  : [
      'button_action: ' + (action || '-'),
      'model: ' + (model || '-'),
      'button_text: ' + (buttonText || '-'),
      'button_payload: ' + (payload || '-'),
    ];

const textBody = textLines.join('\n');

msg.type = 'text';
msg.text = { body: textBody };
delete msg.button;
if (msg.interactive) delete msg.interactive;

return [{ json: item }];

const exactYes = 'SI tengo visa americana';
const exactNo = 'NO tengo visa americana';

const rawMessage = $json.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const buttonText = String($json.button_text || '').trim();
const plainText = String(rawMessage?.text?.body || '').trim();
const responseText = buttonText || plainText;

if (![exactYes, exactNo].includes(responseText)) {
  return [];
}

const unixTimestamp = Number($json.timestamp || rawMessage?.timestamp || 0);
const timestampUtc = unixTimestamp
  ? new Date(unixTimestamp * 1000).toISOString()
  : new Date().toISOString();

return [{
  json: {
    TIMESTAMP_UTC: timestampUtc,
    PHONE_NUMBER: String($json.wa_id || rawMessage?.from || '').trim(),
    PROFILE_NAME: String($json.profile_name || '').trim(),
    RESPONSE_TEXT: responseText,
    RESPONSE_SHORT: responseText === exactYes ? 'SI' : 'NO',
    MESSAGE_ID: String($json.message_id || rawMessage?.id || '').trim(),
    TEMPLATE_NAME: 'hyundai_fifa_visa_check_ec',
    COUNT_VALUE: '1',
  },
}];
